def contains(path, text, ignore_if_missing=False):
    """
    Return True if the given text is found in the file, otherwise return False

    CLI Example:

    .. code-block:: bash

        salt '*' file.contains /etc/motd root
    """
    if not os.path.isfile(path):
        if ignore_if_missing:
            return False
        else:
            raise SaltInvocationError(
                'File not found: {0}'.format(path)
            )

    with salt.utils.fopen(path, 'rb') as fp_:
        if salt.utils.istextfile(fp_):
            try:
                data = salt.utils.stringutils.to_unicode(fp_.read())
            except UnicodeDecodeError:
                log.error(
                    'Failed to read file {0} as unicode'.format(path)
                )
                return False
        else:
            data = fp_.read()

    if text in data:
        return True
    return False


